// Helper function to extract structured data from recipe schema or DOM
async function extractRecipe(url) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

  return await browserjs(tabId, () => {
    // 1. Try to find schema.org Recipe JSON-LD
    const jsonLdScripts = Array.from(document.querySelectorAll('script[type="application/ld+json"]'));
    let recipeLd = null;
    for (const script of jsonLdScripts) {
      try {
        const parsed = JSON.parse(script.innerText);
        if (parsed['@type'] === 'Recipe') recipeLd = parsed;
        else if (Array.isArray(parsed['@graph'])) {
          const found = parsed['@graph'].find(item => item['@type'] === 'Recipe');
          if (found) recipeLd = found;
        }
      } catch (e) {}
    }

    // Basic extraction
    const title = recipeLd?.name || document.querySelector('h1')?.innerText || document.title;
    const ratingValue = recipeLd?.aggregateRating?.ratingValue;
    const reviewCount = recipeLd?.aggregateRating?.reviewCount || recipeLd?.aggregateRating?.ratingCount;
    const ingredients = recipeLd?.recipeIngredient || 
      Array.from(document.querySelectorAll('.wprm-recipe-ingredient, .ingredient, [class*="ingredient"] li, ul[class*="ingredient"] li')).map(el => el.innerText.trim()).filter(Boolean);
    const instructions = recipeLd?.recipeInstructions || 
      Array.from(document.querySelectorAll('.wprm-recipe-instruction, .instruction, [class*="instruction"] li, ol[class*="instruction"] li')).map(el => el.innerText.trim()).filter(Boolean);

    return {
      title,
      ratingValue,
      reviewCount,
      ingredients: ingredients.slice(0, 20),
      instructionsText: Array.isArray(instructions) ? instructions.map(i => typeof i === 'string' ? i : (i.text || i.name || '')).join('\n') : String(instructions),
      url: window.location.href
    };
  });
}

