    const reviewCount = recipe?.aggregateRating?.reviewCount || recipe?.aggregateRating?.ratingCount || '';
    const ingredients = recipe?.recipeIngredient || 
      Array.from(document.querySelectorAll('.wprm-recipe-ingredient, .ingredient, [class*="ingredient"] li')).map(el => el.innerText.trim()).filter(Boolean);
    const instructions = Array.isArray(recipe?.recipeInstructions) 
      ? recipe.recipeInstructions.map(i => typeof i === 'string' ? i : (i.text || i.name || '')).slice(0, 10)
      : Array.from(document.querySelectorAll('.wprm-recipe-instruction, .instruction, [class*="instruction"] li')).map(el => el.innerText.trim()).filter(Boolean).slice(0, 10);

    return {
      title,
      rating,
      reviewCount,
      ingredients: ingredients.slice(0, 15),
      instructions: instructions.slice(0, 8),
      url: window.location.href,
      bodyExcerpt: document.body.innerText.slice(0, 500)
    };
