const tab4Id = 787784546;

// Let's inspect the state of tab 4 (YouTube video)
const playStatus = await browserjs(tab4Id, async () => {
  // Check for consent dialog or reject/accept buttons
  const buttons = Array.from(document.querySelectorAll('button, ytd-button-renderer'));
  for (const b of buttons) {
    const txt = b.innerText.toLowerCase();
    if (txt.includes('accept all') || txt.includes('agree') || txt.includes('reject all')) {
      b.click();
    }
  }

  // Find video element
  const video = document.querySelector('video');
  if (video) {
    try {
      video.muted = true; // muting helps autoplay pass browser restrictions
      await video.play();
    } catch(e) {
      console.log("Play error:", e.message);
    }
    return {
      found: true,
      paused: video.paused,
      currentTime: video.currentTime,
      duration: video.duration,
      src: video.src
    };
  }
  return { found: false };
});

console.log("YouTube Play Status:", JSON.stringify(playStatus, null, 2));

